BEGIN;
CREATE EXTENSION IF NOT EXISTS pgtap WITH SCHEMA extensions;
SET LOCAL search_path = public, extensions;
SELECT no_plan();
INSERT INTO auth.users(id,email) VALUES ('00000000-0000-4000-a074-000000000001','voice-opening@example.test');
INSERT INTO public.businesses(id,owner_id,name,business_type,slug) VALUES ('ea848911-ef72-44a6-8cf3-c47b3959be26','00000000-0000-4000-a074-000000000001','Voice','general','voice-074');
INSERT INTO public.voice_pilot_settings(business_id,enabled) VALUES ('ea848911-ef72-44a6-8cf3-c47b3959be26',true);
INSERT INTO public.subscriptions(business_id,stripe_customer_id,stripe_subscription_id,plan,status) VALUES ('ea848911-ef72-44a6-8cf3-c47b3959be26','cus_voice','sub_voice','sms_and_chat','active');
INSERT INTO public.contacts(id,business_id,phone_number,source_channel) VALUES ('20000000-0000-4000-a074-000000000001','ea848911-ef72-44a6-8cf3-c47b3959be26','+15555550101','voice');
INSERT INTO public.conversations(id,business_id,contact_id,channel) VALUES ('30000000-0000-4000-a074-000000000001','ea848911-ef72-44a6-8cf3-c47b3959be26','20000000-0000-4000-a074-000000000001','voice');
INSERT INTO public.voice_sessions(id,business_id,conversation_id,call_control_id,call_session_id,caller_phone,called_phone,response_mode,status,reserved_seconds) VALUES ('40000000-0000-4000-a074-000000000001','ea848911-ef72-44a6-8cf3-c47b3959be26','30000000-0000-4000-a074-000000000001','control','session','+15555550101','+15742638634','voice','active',600);

INSERT INTO public.voice_pilot_testers(business_id,phone_number) VALUES ('ea848911-ef72-44a6-8cf3-c47b3959be26','+15555550101');
SELECT is(public.voice_action_allowed('40000000-0000-4000-a074-000000000001','contact'),false,'actions default off');
UPDATE public.voice_pilot_settings SET contacts_enabled=true;
SELECT ok(public.voice_action_allowed('40000000-0000-4000-a074-000000000001','contact'),'explicit contact switch allows active tester');
SELECT is(public.voice_action_allowed('40000000-0000-4000-a074-000000000001','signup'),false,'contact flag cannot grant texting');
SELECT public.record_voice_fragment('40000000-0000-4000-a074-000000000001','request','customer','My name is Bryan',100,200);
SELECT lives_ok($$SELECT public.propose_voice_action('40000000-0000-4000-a074-000000000001','contact',repeat('a',64),'{}','May I save Bryan?',ARRAY['request'])$$,'proposal records caller evidence');
SELECT is((SELECT count(*)::integer FROM public.voice_actions),1,'one proposal');
SELECT lives_ok($$SELECT public.propose_voice_action('40000000-0000-4000-a074-000000000001','contact',repeat('a',64),'{}','May I save Bryan?',ARRAY['request'])$$,'duplicate returns same action');
SELECT is((SELECT count(*)::integer FROM public.voice_actions),1,'duplicate does not create a second action');
SELECT throws_ok($$SELECT public.claim_voice_action('40000000-0000-4000-a074-000000000001',(SELECT id FROM public.voice_actions),ARRAY['readback'],ARRAY['yes'])$$,'P0001','voice action not confirmable','no action without playback');
SELECT throws_ok($$SELECT public.propose_voice_action('40000000-0000-4000-a074-000000000001','contact',repeat('b',64),'{"kind":"contact","name":"Brian","phone":"+15555550101","email":"brian@example.test"}','May I save Brian?',ARRAY['foreign'])$$,'P0001','request transcript evidence missing','reject fabricated evidence');
SELECT lives_ok($$SELECT public.propose_voice_action('40000000-0000-4000-a074-000000000001','contact',repeat('b',64),'{"kind":"contact","name":"Brian","phone":"+15555550101","email":"brian@example.test"}','May I save Brian?',ARRAY['request'])$$,'correction replaces proposal');
SELECT is((SELECT count(*)::integer FROM public.voice_actions WHERE status='superseded'),1,'old confirmation cannot run');
-- A complete readback and a subsequent confirmation have independent evidence.
UPDATE public.voice_actions SET created_at=clock_timestamp()-interval '5 seconds';
SELECT public.record_voice_fragment('40000000-0000-4000-a074-000000000001','readback','assistant','May I save Brian?',210,400);
UPDATE public.voice_transcript_fragments SET received_at=clock_timestamp()-interval '1 second' WHERE event_id='readback';
SELECT ok(public.mark_voice_action_playback('40000000-0000-4000-a074-000000000001',(SELECT id FROM public.voice_actions WHERE status='awaiting_confirmation'),'readback',200),'phone playback mark acknowledged');
SELECT public.record_voice_fragment('40000000-0000-4000-a074-000000000001','yes','customer','Yes',500,550);
UPDATE public.voice_transcript_fragments SET received_at=clock_timestamp()+interval '1 second' WHERE event_id='yes';
SELECT lives_ok($$SELECT public.claim_voice_action('40000000-0000-4000-a074-000000000001',(SELECT id FROM public.voice_actions WHERE status='awaiting_confirmation'),ARRAY['readback'],ARRAY['yes'])$$,'valid confirmation claims action');
SELECT is((SELECT count(*)::integer FROM public.voice_actions WHERE status='executing'),1,'one action is executing');
SELECT is((SELECT count(*)::integer FROM public.voice_actions WHERE source_message_id IS NOT NULL),1,'one durable confirmed source message');
SELECT lives_ok($$SELECT public.claim_voice_action('40000000-0000-4000-a074-000000000001',(SELECT id FROM public.voice_actions WHERE status='executing'),ARRAY['readback'],ARRAY['yes'])$$,'duplicate claim returns stored action');
SELECT is((SELECT count(*)::integer FROM public.voice_actions WHERE source_message_id IS NOT NULL),1,'duplicate claim does not add source message');
SELECT lives_ok($$SELECT public.save_voice_action_contact((SELECT id FROM public.voice_actions WHERE status='executing'))$$,'confirmed contact saves atomically');
SELECT is((SELECT name FROM public.contacts LIMIT 1),'Brian','confirmed name stored');
SELECT is((SELECT email FROM public.contacts LIMIT 1),'brian@example.test','confirmed email stored');
UPDATE public.contacts SET name='Existing Name',email='existing@example.test';
SELECT is((public.save_voice_action_contact((SELECT id FROM public.voice_actions WHERE status='executing'))->'conflicts')::text,'["name", "email"]','existing contact conflicts are retained for review');
SELECT is((SELECT email FROM public.contacts LIMIT 1),'existing@example.test','caller ID does not overwrite historical email');
SELECT public.record_voice_fragment('40000000-0000-4000-a074-000000000001','correction','customer','Actually, change that',600,650);
SELECT is(public.voice_action_execution_current((SELECT id FROM public.voice_actions WHERE status='executing')),false,'new caller speech fences unsubmitted effects');
UPDATE public.businesses SET operations_suspended_at=now() WHERE id='ea848911-ef72-44a6-8cf3-c47b3959be26';
SELECT is(public.voice_action_allowed('40000000-0000-4000-a074-000000000001','contact'),false,'suspension immediately blocks actions');
SELECT ok(NOT has_function_privilege('authenticated','public.claim_voice_action(uuid,uuid,text[],text[])','EXECUTE'),'caller cannot invoke claim');
SELECT ok(NOT has_table_privilege('authenticated','public.voice_actions','INSERT'),'caller cannot forge action');
SELECT * FROM finish();
ROLLBACK;
